toolScript:
// Constants
        const CREDIT_CARD_WIDTH_MM = 85.60;
        const DEFAULT_PPI = 96; // Fallback
        // State
        let pixelsPerMm = 3.78; // roughly 96ppi / 25.4
        let currentUnit = 'mm';
        // DOM Elements
        const slider = document.getElementById('calibration-slider');
        const box = document.getElementById('calibrator-box');
        const calZone = document.getElementById('calibration-zone');
        const rulerZone = document.getElementById('ruler-zone');
        const rulerContainer = document.getElementById('actual-ruler');
        const ppiDisplay = document.getElementById('ppi-display');
        // Initialization
        document.addEventListener('DOMContentLoaded', () => {
            // Set initial slider position to a reasonable default (approx 300px for desktop)
            slider.value = 320;
            updateBoxSize();
        });
        // Events
        slider.addEventListener('input', updateBoxSize);
        function updateBoxSize() {
            const width = slider.value;
            box.style.width = width + 'px';
        }
        function adjustFine(amount) {
            let current = parseFloat(slider.value);
            slider.value = current + amount;
            updateBoxSize();
        }
        function finalizeCalibration() {
            const boxWidthPx = parseFloat(box.style.width);
            // Calculate scale
            pixelsPerMm = boxWidthPx / CREDIT_CARD_WIDTH_MM;
            const ppi = pixelsPerMm * 25.4;
            // Update UI
            ppiDisplay.innerText = Math.round(ppi);
            calZone.classList.add('hidden');
            rulerZone.classList.remove('hidden');
            renderRuler();
            showToast("Calibration Locked!");
        }
        function resetCalibration() {
            calZone.classList.remove('hidden');
            rulerZone.classList.add('hidden');
            ppiDisplay.innerText = "--";
        }
        function setUnits(unit) {
            currentUnit = unit;
            // Toggle active button styles
            document.querySelectorAll('.preset-btn').forEach(btn => {
                btn.classList.remove('bg-blue-100', 'border-blue-500', 'text-blue-800');
            });
            document.getElementById(`btn-${unit}`).classList.add('bg-blue-100', 'border-blue-500', 'text-blue-800');
            renderRuler();
        }
        function renderRuler() {
            rulerContainer.innerHTML = ''; // Clear existing
            const rulerLengthMm = 300; // 30cm ruler
            const rulerLengthIn = 12; // 12 inch ruler
            let totalUnits = currentUnit === 'mm' ? rulerLengthMm : rulerLengthIn;
            let pixelsPerUnit = currentUnit === 'mm' ? pixelsPerMm : (pixelsPerMm * 25.4);
            // Set container width
            rulerContainer.style.width = (totalUnits * pixelsPerUnit + 50) + 'px';
            for (let i = 0; i <= totalUnits; i++) {
                const tick = document.createElement('div');
                tick.style.left = (i * pixelsPerUnit) + 'px';
                // Determine tick type
                let isMajor = false;
                if (currentUnit === 'mm') {
                    if (i % 10 === 0) {
                        tick.className = 'tick major';
                        isMajor = true;
                    } else if (i % 5 === 0) {
                        tick.className = 'tick medium';
                    } else {
                        tick.className = 'tick minor';
                    }
                } else {
                    // Inches
                    tick.className = 'tick major'; // We do subdivisions differently for inches usually, but keeping simple loop for now
                    isMajor = true;
                    // Add 1/16th ticks for inches (nested loop would be better, but simpler here)
                    if (i < totalUnits) {
                        for (let j = 1; j < 16; j++) {
                            const subTick = document.createElement('div');
                            subTick.style.left = ((i + j / 16) * pixelsPerUnit) + 'px';
                            subTick.className = (j % 8 === 0) ? 'tick medium' : (j % 4 === 0 ? 'tick minor' : 'tick minor h-2 opacity-40');
                            if (j % 8 === 0) subTick.style.height = "15px";
                            else if (j % 4 === 0) subTick.style.height = "10px";
                            else subTick.style.height = "6px";
                            rulerContainer.appendChild(subTick);
                        }
                    }
                }
                rulerContainer.appendChild(tick);
                if (isMajor) {
                    const label = document.createElement('span');
                    label.className = 'tick-label';
                    label.innerText = i;
                    label.style.left = (i * pixelsPerUnit) + 'px';
                    rulerContainer.appendChild(label);
                }
            }
        }
        function showToast(msg) {
            const toast = document.createElement('div');
            toast.className = "fixed top-24 left-1/2 -translate-x-1/2 bg-slate-800 text-white px-8 py-3 rounded-full shadow-2xl z-[100] animate-bounce font-black text-xs uppercase tracking-widest border border-blue-500";
            toast.innerText = msg;
            document.body.appendChild(toast);
            setTimeout(() => toast.remove(), 4000);
        }
        // --- SCROLL LOGIC ---
